import * as THREE from 'three/webgpu';
import { texture, uv, vec4, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-3-label';

  const pos = config.scenePosition?.position ?? [3.2, 1, 0.06];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const width = 0.9;
  const height = width * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const tex = ctx.textureLoader('/prism-mock/home/nodes/floating-accent.png');
  if (tex) {
    tex.colorSpace = THREE.SRGBColorSpace;
    material.colorNode = texture(tex, uv());
  } else {
    material.colorNode = vec4(color(0x16161d), 1.0);
  }

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'card-plane';
  group.add(plane);

  const textMeshes = [];
  const textContent = config.textContent ?? [];
  for (const item of textContent) {
    const size =
      item.role === 'headline'
        ? 0.34
        : item.role === 'body'
        ? 0.13
        : item.role === 'subhead'
        ? 0.2
        : item.role === 'caption'
        ? 0.09
        : 0.34;

    const textMesh = ctx.fontAtlas.createText({
      text: item.text ?? 'Journal 3',
      font: 'Lora',
      weight: item.weight ?? 400,
      size,
      color: '#e8ecf2',
      align: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
    textMeshes.push(textMesh);
  }

  const baseY = pos[1];
  const baseScale = scl[0];

  let hoverTl = null;
  let pressTl = null;

  group.userData.handlers = {
    onPointerOver: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerOut: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerDown: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: baseScale * 0.97,
        y: baseScale * 0.97,
        z: baseScale * 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: baseScale,
        y: baseScale,
        z: baseScale,
        duration: 0.12,
        ease: 'back.out',
      });
      if (ctx.emit) {
        ctx.emit('hub-journal.select');
      }
    },
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
    for (const textMesh of textMeshes) {
      if (textMesh.userData?.cleanup) {
        textMesh.userData.cleanup();
      } else {
        if (textMesh.geometry) textMesh.geometry.dispose();
        if (textMesh.material) textMesh.material.dispose();
      }
    }
  };

  return group;
}
